 function storedMember(row, rosterDocument, aggregate) {
 const stored = rosterDocument?.characters?.[row.id] || null;
 const overloadTotals = aggregate ? aggregate(stored || row.id) : { activeLines: 0 };
 const growth = stored ? {
 level: finite(stored.level, 400),
 limitBreak: finite(stored.limitBreak, 0),
 coreLevel: finite(stored.coreLevel, 0),
 bond: finite(stored.bond, 30),
 skills: clone(stored.skills || { skill1: 10, skill2: 10, burst: 10 }),
 favoriteItemPhase: finite(stored.favoriteItemPhase, 0),
 ...(stored.equipmentAttack != null && Number.isFinite(Number(stored.equipmentAttack)) ? { equipmentAttack: Math.max(0, Number(stored.equipmentAttack)) } : {}),
 ...(stored.equipmentHp != null && Number.isFinite(Number(stored.equipmentHp)) ? { equipmentHp: Math.max(0, Number(stored.equipmentHp)) } : {}),
 ...(stored.equipmentDefense != null && Number.isFinite(Number(stored.equipmentDefense)) ? { equipmentDefense: Math.max(0, Number(stored.equipmentDefense)) } : {}),
 equipmentObservedSlots: finite(stored.equipmentObservedSlots, 0)
 } : { level: 400, limitBreak: 0, coreLevel: 0, bond: 30, skills: { skill1: 10, skill2: 10, burst: 10 }, favoriteItemPhase: 0, equipmentObservedSlots: 0 };
 // 한돌과 코어 강화는 각각 전투 스탯 +2%로 직접 반영하고, 스킬 레벨은
 // 별도 계수 엔진이 캐릭터별 사격·패킷·버프·CDR에 적용합니다.
 const r3LevelStats = global.NIKKE_R3_DATA_API?.statAtLevel?.(row, growth.level) || null;
 const r3LevelFactor = global.NIKKE_R3_DATA_API?.combatLevelRatio?.(row, growth.level, 400, 'atk') || 1;
 const statGrowthFactor = r3LevelFactor * (1 + 0.02 * (growth.limitBreak + growth.coreLevel));
 return {
 ...row,
 owned: stored?.owned === true,
 cubeId: stored?.cubeId || 'none',
 manualRatio: finite(stored?.manualRatio, 0),
 measuredCoeff: finite(stored?.measuredCoeff, 1),
 overloadTotals,
 growth,
 r3LevelStats,
 statGrowthFactor,
 buildFingerprint: fingerprint('build', {
 characterId: row.id,
 cubeId: stored?.cubeId || 'none',
 manualRatio: finite(stored?.manualRatio, 0),
 growth,
 overloadTotals
 })
 };
 }

